export namespace CircuitState {
    let CLOSED: string;
    let OPEN: string;
    let HALF_OPEN: string;
}
/**
 * Circuit breaker implementation to prevent cascading failures
 */
export class CircuitBreaker {
    constructor(options?: {});
    options: {
        enabled: boolean;
        failureThreshold: any;
        resetTimeout: any;
        halfOpenMaxAttempts: any;
        onCircuitOpen: any;
        onCircuitClose: any;
        onCircuitHalfOpen: any;
    };
    circuits: Map<any, any>;
    /**
     * Get or create circuit for a rule
     * @param {string} ruleId
     * @returns {Object}
     */
    getCircuit(ruleId: string): Object;
    /**
     * Execute function with circuit breaker protection
     * @param {string} ruleId
     * @param {Function} fn - Async function to execute
     * @returns {Promise<any>}
     */
    execute(ruleId: string, fn: Function): Promise<any>;
    /**
     * Record successful execution
     * @param {string} ruleId
     */
    recordSuccess(ruleId: string): void;
    /**
     * Record failed execution
     * @param {string} ruleId
     */
    recordFailure(ruleId: string): void;
    /**
     * Open circuit (start rejecting requests)
     * @param {string} ruleId
     */
    openCircuit(ruleId: string): void;
    /**
     * Transition to half-open state (test if recovered)
     * @param {string} ruleId
     */
    halfOpenCircuit(ruleId: string): void;
    /**
     * Close circuit (resume normal operation)
     * @param {string} ruleId
     */
    closeCircuit(ruleId: string): void;
    /**
     * Get circuit state for a rule
     * @param {string} ruleId
     * @returns {string}
     */
    getState(ruleId: string): string;
    /**
     * Manually reset circuit to closed state
     * @param {string} ruleId
     */
    reset(ruleId: string): void;
    /**
     * Get statistics
     * @returns {Object}
     */
    getStats(): Object;
    /**
     * Cleanup timers
     */
    destroy(): void;
}
